INSERT INTO `tasks` (`task_id`, `project_id`, `sprint_id`, `assignee_id`, `reporter_id`, `type_id`, `status_id`, `priority_id`, `task_title`, `description`, `story_points`, `created_at`, `due_date`, `completed_at`) VALUES
(1, 1, NULL, NULL, 11, 1, 1, 3, 'Автоматизувати REST API для проєктів для внутрішньої команди', 'Необхідно виконати задачу з урахуванням вимог проєкту та поточного стану системи.', 2.0, '2025-02-12 10:30:00', '2025-02-15', NULL),
(2, 1, 1, 11, 1, 4, 5, 2, 'Інтегрувати панель project-менеджера для інтеграції з зовнішнім сервісом', 'Після реалізації потрібно провести перевірку, code review та оновити документацію. Fall citizen about reveal rest.', 13.0, '2025-01-23 12:30:00', '2025-02-06', NULL),
(3, 1, NULL, NULL, 2, 6, 6, 4, 'Перевірити валідацію вхідних даних для адміністративної частини', 'Після реалізації потрібно провести перевірку, code review та оновити документацію.', 1.0, '2025-04-09 15:30:00', '2025-04-30', '2025-04-29 11:00:00'),
